def transform(grid):
    # The separator rows and column divide the grid into six panels.
    row_starts = [0, 5, 10]
    col_starts = [0, 4]
    out = []
    for rs in row_starts:
        row = []
        for cs in col_starts:
            panel = [grid[r][cs:cs + 3] for r in range(rs, rs + 4)]
            counts = {}
            for line in panel:
                for value in line:
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            marks = sum(v != background for line in panel for v in line)
            row.append(1 if marks > 1 else 7)
        out.append(row)
    return out
